// As in ActorManagerParent.sys.mjs, but with single-site and single-page
// message manager groups added.
FindBar: {
  parent: {
    esModuleURI: "moz-src:///toolkit/actors/FindBarParent.sys.mjs",
  },
  child: {
    esModuleURI: "moz-src:///toolkit/actors/FindBarChild.sys.mjs",
    events: {
      keypress: { mozSystemGroup: true },
    },
  },

  allFrames: true,
  safeForUntrustedWebProcess: true,
  messageManagerGroups: [
    "browsers",
    "mail-message",
    "single-site",
    "single-page",
    "test",
    "",
  ],
